#!/usr/bin/env node
/**
 * Adds the camera declarations to the generated Android manifest.
 *
 * Neither `@capacitor/camera` nor `@capacitor-mlkit/barcode-scanning` declares
 * `CAMERA` in its own manifest — both expect the application to do it. Without
 * it Android never shows a permission prompt and every camera call fails
 * silently, which is exactly how the first APK shipped: barcode scanning and
 * label OCR were both dead with no error and no way to grant anything.
 *
 * The `android/` directory is generated by `cap add android` in CI rather than
 * committed, so this patch runs after generation. It is idempotent.
 *
 * Usage: node scripts/patch-android-manifest.mjs [path/to/AndroidManifest.xml]
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';

const MANIFEST = process.argv[2] ?? 'android/app/src/main/AndroidManifest.xml';

/**
 * Hardware is declared `required="false"` so the app stays installable on
 * devices without a camera; the scanners already degrade to manual entry.
 */
const DECLARATIONS = [
  '<uses-permission android:name="android.permission.CAMERA" />',
  '<uses-feature android:name="android.hardware.camera" android:required="false" />',
  '<uses-feature android:name="android.hardware.camera.flash" android:required="false" />',
];

if (!existsSync(MANIFEST)) {
  console.error(`No manifest at ${MANIFEST}. Run \`npx cap add android\` first.`);
  process.exit(1);
}

let xml = readFileSync(MANIFEST, 'utf8');

/**
 * Portrait only.
 *
 * Nothing in the app is designed for landscape — the gauge, the diary and the
 * tab bar all assume a tall window — and a rotation mid-entry destroys and
 * recreates the activity, which drops whatever was half-typed into a sheet.
 * `orientation|screenSize|keyboardHidden` in configChanges keeps the activity
 * alive for the configuration changes Android would otherwise restart it for.
 */
if (!/android:screenOrientation=/.test(xml)) {
  xml = xml.replace(
    /(<activity\b[^>]*?)(\s*>)/,
    '$1\n            android:screenOrientation="portrait"$2',
  );
  console.log('Locked the main activity to portrait.');
}

const missing = DECLARATIONS.filter((line) => {
  const name = /android:name="([^"]+)"/.exec(line)?.[1];
  return name ? !xml.includes(`android:name="${name}"`) : true;
});

if (missing.length === 0) {
  console.log('Manifest already declares camera access.');
  process.exit(0);
}

// Insert immediately before </manifest> so the block sits alongside whatever
// the plugins merged in.
const block = missing.map((line) => `    ${line}`).join('\n');
xml = xml.replace(/(\n?)<\/manifest>/, `\n\n${block}\n</manifest>`);
writeFileSync(MANIFEST, xml);

console.log(`Added ${missing.length} declaration(s) to ${MANIFEST}:`);
for (const line of missing) console.log(`  ${line.replace(/\s+/g, ' ')}`);
